-- | ONE-OFF BACKWARDS-COMPATIBILITY HACK. Do not extend this as a general mechanism.
--
-- These are the transactions that ran out of gas on the live chains under the
-- ORIGINAL SolidVM gas schedule (400,000 budget, per-statement charges). The
-- revised operation metering prices work differently, so some of them would
-- now finish inside the budget and write state the real chain never wrote,
-- which breaks the state root when replaying history.
--
-- No single budget reproduces history: the heaviest transaction that
-- historically SUCCEEDED costs 440,171 under the revised metering, while
-- transactions that historically FAILED cost as little as ~435,700. So the
-- historical failures are pinned here by transaction hash and are failed as
-- out-of-gas without being executed (see addTransaction in
-- Blockchain.BlockChain).
--
-- The lists were taken from the public nodes' transaction results:
--   upquark: complete through block 981473
--   helium:  complete through block 1165065
-- A transaction that runs out of gas under the old schedule after those
-- heights, before every validator runs the revised metering, must be added.
-- Nothing mined under the revised metering ever belongs here.
module Blockchain.HistoricalOutOfGas (isHistoricalOutOfGasTx) where

import Blockchain.EthConf (ethConf, networkConfig)
import qualified Blockchain.EthConf.Model as Conf
import Blockchain.Forks (heliumNetworkID, upquarkNetworkID)
import Blockchain.Strato.Model.ExtendedWord (Word256)
import Blockchain.Strato.Model.Keccak256
import qualified Data.Set as S

-- | True for a transaction that must be replayed as out-of-gas on this network.
isHistoricalOutOfGasTx :: Keccak256 -> Bool
isHistoricalOutOfGasTx = (`S.member` historicalOutOfGasTxs)

{-# NOINLINE historicalOutOfGasTxs #-}
historicalOutOfGasTxs :: S.Set Keccak256
historicalOutOfGasTxs = S.fromList . map unsafeCreateKeccak256FromWord256 $
  let net = Conf.networkID $ networkConfig ethConf
   in if net == upquarkNetworkID then upquarkOutOfGasTxs
      else if net == heliumNetworkID then heliumOutOfGasTxs
      else []

